import { inject } from '@angular/core';
import { CanActivateFn, Router } from '@angular/router';

export const adminGuard: CanActivateFn = async () => {
  const session = await inject(AuthService).loadSession();
  // After the await: no injection context, so NG0203
  return session.isAdmin || inject(Router).parseUrl('/login');
};

import { inject } from '@angular/core';
import { CanActivateFn, Router } from '@angular/router';

export const adminGuard: CanActivateFn = async () => {
  // Resolve every dependency before the first await
  const auth = inject(AuthService);
  const router = inject(Router);
  const session = await auth.loadSession();
  return session.isAdmin || router.parseUrl('/login');
};

