import { Component, DestroyRef, inject, input, signal } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';

@Component({ selector: 'app-price-ticker', template: `{{ price() }}` })
export class PriceTicker {
  readonly symbol = input.required<string>();
  readonly price = signal(0);
  private readonly feed = inject(PriceFeed);
  private readonly destroyRef = inject(DestroyRef);

  ngOnInit() {
    // Inputs are ready here, but the injection context is gone:
    // pass the DestroyRef that a field initializer captured.
    this.feed.prices(this.symbol())
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe((p) => this.price.set(p));
  }
}
